def compute(vars):
    old_value = vars["v1"]
    new_value = vars["v2"]
    result = 2018 if old_value > new_value else 2019 if new_value > old_value else None
    return {
        "value": result,
        "trace": {
            "2018_value": old_value,
            "2019_value": new_value,
            "output_meta": {"currency": None, "scale": "ones", "unit": "year"}
        }
    }
